class OutboundCallRequest(TypedDict):
    """One phone call: who to dial, from which of your numbers, and what runs.

    `vars` comes from `AgentPlanRequest` and lasts exactly as long as this call.
    """

    # A complete agent definition, run for this call and stored nowhere. Mutually
    # exclusive with `agent_id`.
    agent: NotRequired[AgentConfig | None]
    # An agent in this workspace. Mutually exclusive with `agent`.
    agent_id: NotRequired[str | None]
    # Changes layered on top of whichever base was named. Absent keys keep the base
    # value, an explicit null clears the field, objects deep-merge and lists replace.
    agent_override: NotRequired[AgentOverride | None]
    # Run several agents on this call, defined here. Mutually exclusive with `agent_id`
    # / `agent` / `agent_version` / `agent_override`.
    agent_team: NotRequired[AgentTeam | None]
    # Which version of `agent_id` to run. Omit for the published one. `"draft"` runs the
    # unpublished working copy — validated and tool-pinned at request time, and refused
    # with the publish errors if it does not hold together.
    agent_version: NotRequired[int | Literal["draft"] | None]
    from_phone_number_id: str
    to: str
    userdata: NotRequired[dict[str, Any] | None]
    # Values for the variables the agents on this session declare, read as {{vars.name}}
    # in a prompt, a greeting and a tool. They override each agent's declared default
    # and reach every agent the session runs, including a handoff target. Unlike
    # `userdata`, which describes the PERSON and is kept on their contact record, these
    # describe THIS session and are gone with it. Strings only; an empty string is a
    # deliberate blank, not a request for the default. The model can see them, so put
    # credentials in a workspace secret and read {{secrets.NAME}} from a tool instead.
    vars: NotRequired[dict[str, str] | None]


